					"**紫微（庙旺）** 在兄弟：",
					'兄弟宫紫微，兄弟姐妹中有贵气，往往有一位出类拔萃、地位较高的兄弟姐妹；或自己在兄弟中排行贵显，受兄弟敬重。合伙关系上，合伙人气场强势，各有主见，合作时需明确分工，防止"双帝争权"；若化权，合伙人极为强势；化忌则兄弟不和或合伙破财，需提防。',
